/* 各课程的零基础概念拆解：先认对象，再看数字和符号，最后进入原正文。 */
(()=>{
  const content={
    'ai-foundations':{title:'先认识这门课里的几个角色',parts:[['人工智能、机器学习、深度学习','人工智能是让机器完成智能任务的目标；机器学习是从例子中找规律的一类方法；深度学习用多层神经网络学习这些规律。它们有关联，但不是同一个词。'],['函数是“输入按规则变成输出”','把一张照片记成输入 x，把模型给出的分数记成 y。函数 y=f(x) 的意思是：给定 x，按规则 f 算出 y；模型就是一个由很多可调参数组成的复杂函数。'],['样本和标签','一张训练照片是一个样本；“照片里有猫”是这张照片的标签，也就是这道练习的标准答案。特征是模型从输入里用来判断的线索，例如边缘、颜色或形状。'],['参数、训练和推理','权重与偏置是模型里会被训练调整的参数。训练时用带标签的样本比较预测和答案，再调整参数；推理时把学到的参数用于新照片，通常只做预测。']],example:'例：z=1.5×2−1=2。这里 2 是模型的原始计算分数；它还不是“有猫的概率”。',symbols:'x 表示输入；f 表示计算规则；y 表示输出；w 表示权重；b 表示偏置；z 表示未经概率转换的分数。'},
    tensor:{title:'数字、列表和表格怎样变成张量',parts:[['先数有几层分组','一个数 7 是标量，shape（形状）是 ()；一排数 [2,5,7] 是向量，shape 是 (3,)；两行三列的表是矩阵，shape 是 (2,3)。它们都是张量，只是轴的数量不同。'],['轴是数据的方向','shape (2,3) 中，轴 0 有 2 行，轴 1 有 3 列。索引从 0 开始，所以第二行第三列写作 [1,2]。轴名要结合数据说明：图片常有批次、颜色、高、宽四个方向。'],['先做一行乘一列','[1,2,3] 与 [4,5,6] 做点积：1×4 + 2×5 + 3×6 = 32。矩阵乘法就是把左表每行和右表每列这样相乘再相加。'],['数字类型和放置位置','dtype 表示数字类型，如 float32 能保存小数，uint8 常保存 0–255 的像素整数；device 表示数据放在 CPU 还是 GPU。参加同一运算的张量通常要兼容类型和设备。']],example:'形状 (2,3) @ (3,1) → (2,1)：中间两个 3 对齐并被逐项乘加；左边的 2 行和右边的 1 列留下。',symbols:'shape 是每条轴的长度；@ 表示矩阵乘法；[行,列] 是索引；(N,C,H,W) 常表示批次、通道、高、宽。',advanced:{title:'内存布局选学',text:'张量内存步幅和存储偏移描述程序怎样从底层存储读取元素。它们是理解转置视图和连续性所需的实现细节；先会看 shape 与索引，再回来看它们。'}},
    network:{title:'先算完一个小网络，再看层的名字',parts:[['神经元先做乘加','神经元是一个带参数的小计算单元。输入 x 与权重 w 相乘，再加偏置 b，得到 z=wx+b。权重改变输入的重要程度，偏置整体平移分数。'],['Linear 是带偏置的线性层','PyTorch 的 Linear 通常计算 Wx+b；严格说这是仿射变换，因为有偏置项。多个 Linear 连起来但不夹非线性时，整体仍可合并成一个仿射计算。'],['激活函数加入非线性','ReLU 把负数变成 0，正数保持不变。在线性层之间加入它，网络才能表示弯曲、分段等更复杂的关系。'],['最后的输出仍需按任务解释','分类层给每个类别一个 logit（概率变换前的原始分数）。二分类可以再用 Sigmoid；互斥多分类通常把整组分数交给 Softmax 或直接交给 CrossEntropyLoss。']],example:'两输入算一个分数：x=(2,1)，w=(0.5,−1)，b=1，则 z=0.5×2−1×1+1=1。经过 ReLU 后仍为 1。',symbols:'W 是权重表，x 是输入，b 是偏置，z=Wx+b 是原始分数；ReLU(z)=max(0,z)。',advanced:{title:'SwiGLU 与参数预算',text:'SwiGLU 是 Transformer 前馈模块中的门控结构，不是第一个神经网络必须掌握的组成。先会算 Linear、ReLU 和输出分数，再比较它与其他激活/门控方式，并在相同参数预算下比较。'}},
    losses:{title:'损失先回答“这个答案错得有多重”',parts:[['先分清预测与标签','模型给出的预测是它的答案；标签是已知正确答案。损失函数把两者变成一个数，用来表示预测与训练目标之间的差异。'],['logit 从最后一层的乘加得到','模型最后一层可把输入线索乘权重、求和并加偏置，得到 z=wx+b。这个 z 叫 logit（原始分数），可以为负，不是百分比，也还不是概率。'],['先认概率，再看 Sigmoid','概率在 0 到 1 之间：0 表示不支持，0.5 表示一半，1 表示完全支持；分别可写成 0%、50%、100%。二分类用 Sigmoid 把一个 logit 换成正类概率；z=0 时 p=0.5，z=2 时 p≈0.881。互斥多分类用 Softmax 处理整组分数；多个可以同时成立的标签则分别建模。'],['BCE 的每个符号都对应一件事','二元交叉熵 BCE 的单样本公式是 L=−[y ln(p)+(1−y)ln(1−p)]。y 是 0/1 标准答案，p 是正类概率，1−p 是负类概率，ln 是自然对数。y=1 时只剩 −ln(p)；y=0 时只剩 −ln(1−p)。'],['Softmax 逐项变成共同的概率','logits [2,1,0.1] 先取指数，约为 [7.39,2.72,1.11]；总和约 11.22；各自除以总和，得到 [0.659,0.243,0.099]。exp(z)=e 的 z 次方，Σ 表示求和，因此结果非负且总和为 1。'],['类别编号、独热标签和 CE','真实类别为兔时，类别编号可写作 2（从 0 开始）；独热标签 [0,0,1] 则把正确位置标成 1。多分类交叉熵 CE=−ln(p_true)，只惩罚真实类概率；也可写成各类标签乘对数概率后求负和。p_true=0.1 时损失约 2.303，p_true=0.9 时约 0.105。'],['算完概念再选 PyTorch 接口','BCELoss 输入概率；BCEWithLogitsLoss 输入二分类 logits；CrossEntropyLoss 常见用法输入多分类 logits 与类别编号。后两个接口会在内部使用数值稳定的组合计算，所以训练时不要提前手动做 Sigmoid/Softmax。']],example:'二分类：真实 y=1、预测 p=0.8 → BCE=−ln(0.8)≈0.223；同样 p=0.8 若真实 y=0 → BCE=−ln(0.2)≈1.609。错误答案越自信，惩罚越大。',symbols:'x 是输入线索；w 是权重；b 是偏置；z=wx+b 是 logit；p 是正类概率；y 是 0/1 标签；p_true 是真实类概率；ln 是自然对数；exp(z)=e^z；Σ 表示求和；argmax 只挑最大分数的类别，不计算损失。',advanced:{title:'信息量、熵、KL 与数值稳定性',text:'它们解释交叉熵的统计含义或改善数值计算，属于后续扩展。先会从 logit 到概率、再从真实类概率算损失，基础主线已经闭合。'}},
    gradient:{title:'导数是“参数动一点，损失变多少”',parts:[['先看一个参数','参数 w=1，目标是让它靠近 3，损失 L=(w−3)²=4。把 w 稍微调大，损失会下降；把 w 调小，损失会上升。'],['导数是局部斜率','对 L=(w−3)² 求导，dL/dw=2(w−3)。代入 w=1 得 −4：当前往右增加 w 会让损失下降。偏导是多个参数时，固定其他参数只看其中一个；梯度把所有参数的偏导放在一起。'],['梯度下降走反方向','学习率 η=0.1 时，w_new=1−0.1×(−4)=1.4，新损失为 (1.4−3)²=2.56。负梯度方向让本例的损失降低。'],['链式法则把多步计算串起来','若 u=3x、L=u²，x=2 时 u=6、L=36。先算 dL/du=2u=12，再算 du/dx=3，故 dL/dx=12×3=36。反向传播就是沿计算步骤把这些局部导数相乘并传回去。']],example:'本课小算例：w=1 → 斜率 −4 → 走一步到 1.4 → 损失从 4 降到 2.56。真实网络参数很多，但每步逻辑相同。',symbols:'L 是损失；w 是参数；dL/dw 是损失对参数的导数；η 是学习率；w_new=w−η(dL/dw)。'},
    optimizer:{title:'优化器规定怎样使用梯度更新参数',parts:[['梯度不是更新本身','梯度是模型参数在当前点的变化信号。优化器读取参数和梯度，按一条更新规则计算新参数。'],['SGD 是最简单的一步','SGD 全称 Stochastic Gradient Descent，随机梯度下降。若 w=1、梯度 g=2、学习率 η=0.1，则 w_new=1−0.1×2=0.8。'],['动量让方向更平滑','动量把近期梯度做加权累积；连续几步方向一致时，更新会更有持续性，方向反复时会被平滑。它多保存一个速度状态，不等同于把学习率调大。'],['Adam 同时跟踪方向与尺度','Adam 用一阶移动平均估计梯度方向 m，用二阶移动平均估计梯度平方尺度 v，再据此决定每个参数实际改动多少。它常见且方便，但仍要检查学习率和验证效果。']],example:'最简单 SGD：旧值 1.0，梯度 +2.0，学习率 0.1；新值 1.0−0.2=0.8。',symbols:'g 表示梯度；η 表示学习率；m 表示梯度的平滑平均；v 表示平方梯度的平滑平均。',advanced:{title:'AdamW、权重衰减与混合精度',text:'AdamW 将权重衰减与 Adam 的梯度更新分开；梯度裁剪限制梯度大小；AMP 混合不同精度运算以节约资源。先掌握 SGD 更新，再按需要学习这些训练技巧。'}},
    training:{title:'把一次训练拆成可以数清的步骤',parts:[['样本和标签是一道带答案的练习','样本是输入例子，标签是这道例子的标准答案。训练集用于更新参数；验证集用于观察和选择设置；测试集留到最后作较独立的评估。'],['Batch 是一次拿来计算的一小组','8 张训练图片，每批 2 张，需要 4 个 batch。每个 batch 做一次前向计算、算损失、求梯度和更新参数。'],['Epoch 是完整看一遍训练集','一个 epoch 表示按当前采样方式完整遍历训练数据一次。若没有丢弃最后不足一批的样本，8 张图分成每批 2 张就是 4 次更新；具体尾批处理由程序设置决定。'],['验证与推理不等于更新','验证用于测量当前模型，不把验证答案用于这一步参数更新。train()/eval() 控制 Dropout、BatchNorm 等层的行为；是否记录梯度还需用 no_grad 或 inference_mode 等机制另行控制。']],example:'8 张图 ÷ 每批 2 张 = 4 批；若完整遍历一次，就约有 4 次参数更新。再用独立验证图检查是否能推广。',symbols:'batch 是一批样本；iteration/step 常指一次更新；epoch 是一次完整遍历；DataLoader 负责按设定取数据。',advanced:{title:'文件格式、量化与部署',text:'checkpoint 用来保存模型或训练状态；state_dict 是 PyTorch 的命名参数/状态集合；GGUF、ONNX 等是不同模型文件表示，量化会用较少精度近似数值，运行时负责执行模型。这些不属于理解训练循环的前置。'}},
    regularization:{title:'训练集成绩与新题成绩要一起看',parts:[['泛化是面对没见过的例子','训练集上的好成绩只说明模型能处理参与训练的例子。泛化能力指模型在来源合理的新数据上仍能做对。'],['过拟合像背题','若训练错误率下降而验证错误率升高，模型可能在记住训练图片的偶然细节。欠拟合则是训练和验证都学得不好。先检查划分和标签，再决定是否改模型。'],['正则化不是单一按钮','正则化是降低模型依赖偶然细节的一类办法。Dropout 在训练时随机屏蔽部分激活；权重衰减惩罚较大的参数；早停依据验证表现停止训练。它们机制不同。'],['耐心值 patience','早停通常会记录验证指标最好的轮次；连续若干轮没有改善才停止。停止后往往恢复最好轮次的 checkpoint，不一定使用最后一轮参数。']],example:'训练错误率 10%→2%，验证错误率 12%→25%：这是需要检查的过拟合信号，不是只看训练损失就宣布模型变好了。',symbols:'train 表示训练表现；val 表示验证表现；epoch 是一轮完整遍历；patience 是允许等待改善的轮数。'},
    image:{title:'先看像素，再看图像布局和预处理',parts:[['像素是一个位置上的数字','灰度像素常用一个亮度值；RGB 彩色像素用红、绿、蓝三个数。常见 8 位通道范围是 0–255，具体文件格式和库的约定可能不同。'],['颜色顺序与数组轴是两回事','RGB/BGR 表示颜色通道顺序；HWC/CHW 表示高度、宽度、通道在数组里的排列顺序。OpenCV 常见读取结果是 BGR、HWC；模型常接收 RGB、CHW。'],['缩放与标准化','除以 255 把 0–255 缩到 0–1。标准化通常按 (像素−均值)/标准差 计算；均值和标准差应使用模型训练时约定的值，不能随意套用。'],['Letterbox 保持比例','把 640×480 图像放入 640×640 画布时，等比例缩放后上下补边；预测框映回原图要先扣除补边，再除以缩放比例。']],example:'像素 [0,128,255] 除以 255 后约为 [0,0.502,1]。若 RGB/BGR 顺序弄反，颜色会变；若只换 HWC/CHW，则只是移动数组轴。',symbols:'H/W 是高/宽；C 是颜色通道数；mean 是均值；std 是标准差；缩放值和标准化值不是一回事。'},
    tasks:{title:'先决定答案长什么样',parts:[['分类回答整张图','分类通常给整张图片一个类别，例如“有汽车”。它不告诉你汽车具体在哪里。'],['检测回答每个目标的位置','目标检测为找到的物体给出类别、分数和矩形框；同一张图可能有多个框。'],['分割回答哪些像素属于哪里','语义分割给每个像素预测类别，同类物体不一定分开；实例分割会把同类的每个个体分别圈出来。掩码是像素级的区域标记。'],['其他任务属于不同问题','关键点估计预测有意义的位置；深度估计预测远近；图像生成产生新图像。这些任务可以复用网络模块，但答案形式不同。']],example:'同一张街景：分类“有车”；检测“车在这个矩形里”；实例分割“这辆车轮廓内的像素属于它”。',symbols:'类别是答案标签；框记录矩形位置；mask（掩码）记录像素区域；关键点用坐标表示。'},
    cnn:{title:'卷积是一个小窗口重复做乘加',parts:[['滤镜在图像上逐格移动','卷积核/滤镜是小表格，每个位置有权重。把图像局部数字与权重逐项相乘再相加，得到输出图上的一个数；同一组权重在多个位置重复使用。'],['先算一个简单窗口','3×3 的九个像素与九个权重相乘，九项求和后加偏置，得到一个输出位置。卷积层会用多组滤镜，因此可以输出多张特征图。'],['尺寸由窗口、步幅和补边决定','卷积步幅是卷积窗口每次移动的格数；padding 是边缘补出的格子；dilation 是核内采样间隔。输入 5×5、核 3×3、padding=1、卷积步幅=1 时，输出空间仍为 5×5。'],['通道也参加乘加','彩色输入有多个通道，一组卷积核会在所有输入通道上计算并汇总，再产生输出通道。更深层特征图不保证每个通道都对应固定人类概念。']],example:'尺寸公式单轴示例：floor((5+2×1−3)/1)+1=5。B 是批次数；Cin/Cout 是输入/输出通道数。',symbols:'H/W 表示高和宽；K 是卷积核边长；P 是 padding；S 是卷积步幅；floor 表示向下取整。',advanced:{title:'经典网络与计算量',text:'LeNet、AlexNet、VGG、ResNet 是不同历史时期的网络设计；FLOPs 是运算量估计；感受野是某个输出受原图多大范围影响。先会算一格卷积，再比较这些结构的取舍。'}},
    pooling:{title:'池化把小区域压成一个代表数',parts:[['最大池化选最大的值','窗口 [1,4;3,2] 的最大值是 4。平均池化计算 (1+4+3+2)/4=2.5。池化减少空间格子数，同时也会丢掉精细位置。'],['窗口和步幅决定怎样扫','kernel_size 是窗口大小；池化步幅是窗口移动距离。边界是否补齐、最后不足一个窗口时如何处理，取决于 padding 和 ceil_mode 等设置。'],['全局平均池化','对每个通道各自把所有空间位置求平均，一张 H×W 表变成一个数。输出类别数是否对应通道数，取决于后续网络设计。']],example:'一个 2×2 窗口 [1,4;3,2]：MaxPool 得 4；AvgPool 得 2.5。',symbols:'H/W 表示特征图高宽；kernel_size 是窗口边长；池化步幅表示窗口每次移动几格；全局平均是对空间位置求均值。'},
    iou:{title:'先统一坐标，再计算重叠比例',parts:[['图像坐标从哪里开始','常见图像坐标原点在左上角，x 向右增大、y 向下增大。比较两个框之前，要确认坐标顺序、原图尺寸和坐标是否归一化一致。'],['两种框写法','xyxy=(左上 x、左上 y、右下 x、右下 y)；xywh 在常见检测标签中表示中心 x、中心 y、宽、高。不同库可能用不同约定，要看清文档。'],['交集和并集','交集是两个框共同覆盖区域；并集是至少被一个框覆盖的总区域，面积可用 area1+area2−intersection 计算。'],['IoU 是重叠比例','IoU 全称 Intersection over Union，中文交并比：交集面积÷并集面积，通常在 0 到 1 之间。它量框的位置重叠，不等于模型置信度。']],example:'两个框面积各 100，交集 50：并集=100+100−50=150，IoU=50/150≈0.333。',symbols:'x1,y1,x2,y2 是左上和右下坐标；中心点与宽高要先换成同一种框约定再比。'},
    dataset:{title:'检测数据集由图片、标签和类别表组成',parts:[['每个样本是一张图和对应标注','数据集由样本组成。检测图片通常配同名标签文件；每个目标一行，类别编号要与类别名称表一致。'],['YOLO 标签是一行五个数','常见格式是 class x_center y_center width height。四个框数字除以图片宽高，缩放到 0–1；类别编号从 0 开始。'],['把标签数字还原成像素','1000×500 图片的一行 `0 0.50 0.40 0.20 0.16`：类别 0；框中心 (500,200)；宽 200、高 80。'],['data.yaml 指明数据位置','它通常写数据根路径、train/val 图片位置及 names 类别名称。路径相对哪个目录、是否支持目录/清单文件，应按当前仓库版本确认。']],example:'标签 `0 0.50 0.40 0.20 0.16` 在 1000×500 图上对应中心 (500,200)、框宽 200、高 80。',symbols:'class 是类别编号；x/y 是中心坐标；w/h 是宽高；归一化坐标是除以图像对应边长后的比例。'},
    augmentation:{title:'增强要造出合理的新例子',parts:[['几何变化会移动标签','水平翻转宽度归一化框时，中心 x 变为 1−x；宽高、y 不变。旋转、裁切和缩放都要按同一变换更新框或掩码。'],['颜色变化在像素上发生','HSV 用色相、饱和度、明度描述颜色。调色可以提升光照变化下的适应性，但过度改变可能把真实的颜色线索破坏。'],['Mosaic 拼图','把多张图片裁切、缩放到同一画布；每个框也要同步平移、缩放，并裁掉画布外部分。边界处理会影响标签质量。'],['增强效果要用验证集判断','训练表现变好不代表泛化变好。固定数据与其他参数，一次改一种增强，再看验证指标、目标大小和错误样本。']],example:'框中心 x=0.20，水平翻转后 x′=1−0.20=0.80；如果图翻了而标签没翻，监督就错了。',symbols:'x/y 常指归一化框中心；w/h 是归一化宽高；HSV 分别是色相、饱和度、明度。'},
    metrics:{title:'先逐个预测和真实目标配对，再算指标',parts:[['真阳性 TP','预测类别正确、框满足指定 IoU 条件，并且真实目标还没有被其他预测匹配，才能记为一次 TP。'],['假阳性 FP 与假阴性 FN','报出的预测没有合格真实目标匹配，记为 FP；仍未找到的真实目标记为 FN。一个真实目标不能重复匹配多个预测。'],['Precision 与 Recall','Precision=TP/(TP+FP)，问“我报出的里面有多少正确”；Recall=TP/(TP+FN)，问“真实目标里找到了多少”。'],['F1 和 AP/mAP','F1 用调和平均折中 Precision/Recall。AP 汇总不同置信门槛下的 PR 曲线表现；mAP 再按类别平均。IoU 门槛、曲线插值及评测实现会影响数值，报告时要写清协议。']],example:'3 个真实目标、保留 3 个预测，其中 2 个命中、1 个误报：TP=2, FP=1, FN=1；Precision=2/3，Recall=2/3，F1=2/3。',symbols:'TP 是正确匹配；FP 是错误报出；FN 是漏掉；P/R/F1 分别是查准率、查全率和二者折中。'},
    'data-quality':{title:'先看数据代表不代表未来场景',parts:[['样本多不等于场景多','同一段视频连续帧很相似。若相邻帧分到训练和验证两边，验证图可能和训练图几乎一样，造成虚高成绩。'],['按来源分组切分','先按视频、拍摄地点或对象分组，再把组分到训练/验证/测试集合。这样更接近模型遇到新来源时的表现。'],['数量和分布一起检查','记录每类图片/目标数量、目标大小、场景来源及缺失/损坏标签。只看总体准确率容易掩盖少数类表现。'],['困难负样本','困难负样本是看起来像目标、实际不是目标的背景，例如树影像行人。保留并标明这类例子，有助于发现模型误报。']],example:'把 8 个连拍帧随机拆分，A/B 两组都会混入 train 和 val；按拍摄序列整体分组，验证才检查另一段来源。',symbols:'train/val/test 分别用于训练、调试选择和最终评估；分组字段应能标出同一来源。'},
    transfer:{title:'迁移学习是从已有参数开始适应新任务',parts:[['预训练模型先学过其他例子','预训练权重是模型先前从数据中学到的一组参数。它可能包含可复用的视觉线索，但不保证适合新任务。'],['骨干与输出头','Backbone（骨干）主要提取特征；Head（头部）把特征转换成任务所需的答案。新任务类别不同，常要调整输出头。'],['冻结控制哪些参数更新','冻结通常是让某些参数不参与梯度更新；解冻后它们能继续微调。冻结参数和模型处于 train/eval 模式是两件事。'],['BatchNorm 还要单独考虑','即使参数冻结，BatchNorm 的运行均值/方差仍可能在训练模式下更新；是否切换 eval 要按目标行为设置，不能只看 requires_grad。']],example:'先冻结特征层、只训练新分类头；验证表现仍不足时，再用较小学习率逐步解冻部分层。',symbols:'requires_grad 控制参数是否计算梯度；train()/eval() 控制部分层的运行行为；二者不要混为一谈。'},
    'euler-angles':{title:'先从空间方向认识欧拉角',parts:[['位置和朝向回答不同问题','位置回答“物体在哪里”，朝向回答“物体面向哪里”。把一支箭头放在桌面上，移动它改变位置，原地转动它才改变朝向；欧拉角用三个角来记录这种转动。'],['三个角表示连续的轴向转动','把 x、y、z 看作三条互相垂直的方向，欧拉角就像依次绕这些轴转动的三个角。它不是三个可以随便交换的数字：必须说明每个角对应哪根轴，以及绕固定世界轴还是随物体移动的轴。'],['旋转顺序会改变结果','例如固定世界轴上先绕 X 再绕 Z，与先绕 Z 再绕 X，通常会把一般向量转到不同方向。用角度时还要注意单位：180° 等于 π 弧度；很多程序的正弦和余弦函数要求弧度。'],['万向节锁是参数表达的限制','在某些角度，两个旋转轴会重合，导致两个角不能再独立改变朝向，这叫万向节锁。物体仍然可以转；只是用这一组欧拉角区分朝向会失去一个独立方向。']],example:'固定世界轴上令 v=(1,0,0)，先绕 X 转 90°，向量方向暂时不变；再绕 Z 转 90°，结果为 (0,1,0)。若先绕 Z 再绕 X，结果为 (0,0,1)。',symbols:'X、Y、Z 是空间中的三条坐标轴；α、β、γ 表示三个旋转角；90°=π/2 弧度。具体 XYZ 顺序和轴的含义要按课程或软件约定核对。'},
    quaternion:{title:'先理解旋转是空间里的一个动作',parts:[['三维向量是带方向和长度的箭头','向量 (1,0,0) 指向 x 轴方向；绕原点转动后长度不变，方向改变。角度可用度或弧度表示，三角函数输入通常按弧度。'],['欧拉角用三次轴旋转描述朝向','roll/pitch/yaw 等角度必须说明轴、先后顺序、主动/被动旋转和坐标约定；不同顺序的结果一般不同。某些姿态会让两根转轴重合，形成万向节锁。'],['四元数用四个相关分量表示旋转','单位四元数常写作 q=(cos(θ/2), sin(θ/2)·u)，u 是单位旋转轴。它不是四个独立角度；同一个旋转还可能有 q 与 −q 两种等价表示。'],['先约定再比较','本页互动约定右手坐标、主动旋转、绕 Z 轴、分量顺序 (w,x,y,z)。其他库可能使用不同顺序；组合旋转时乘法顺序会影响结果。']],example:'绕 Z 轴转 90°：θ/2=45°，q=(cos45°,0,0,sin45°)≈(0.707,0,0,0.707)；向量 (1,0,0) 转到 (0,1,0)。',symbols:'θ 是转角；u 是单位轴；sin/cos 输入弧度；q=(w,x,y,z) 的顺序必须按具体库确认。'},
    architecture:{title:'YOLOv5 先提特征、再融合、最后出候选',parts:[['Backbone：逐层提取图像线索','主干网络把像素变成多层特征图。分辨率逐步下降、通道数通常增加；细节和更大范围的语义线索逐渐组合。'],['C3：两条分支再合并','C3 会把输入通道分支，一路经过若干 Bottleneck 变换，另一路保留较直接的信息，最后拼接并融合。具体层数和快捷连接按配置与实现核对。'],['残差捷径保留输入信息','一个残差块可写成 y=F(x)+x：输入 x 沿短路和变换结果相加。相加要求形状相容；若通道/尺寸不同，实际模块可能用投影或其他匹配操作。'],['SPPF 与 Neck','SPPF 用串联池化汇集不同感受范围；Neck 用 FPN 的自上而下与 PAN 的自下而上路径融合多尺度特征；Detect 在 P3/P4/P5 产生多尺度候选。']],example:'640×640 输入常见 P3/P4/P5 空间格为 80×80、40×40、20×20；数字表示特征图格数，不是目标的类别。',symbols:'P3/P4/P5 是不同尺度特征层；Concat 是沿通道拼接；残差 Add 是逐元素相加；每个具体形状以 yolov5l.yaml 为准。'},
    anchors:{title:'网格定位置参考，anchor 定宽高起点',parts:[['网格是把图像划成小格','把 640×640 图片均分成 4×4 教学网格，每格宽高 160。中心点 (0.62,0.37) 落在第 2 行、第 3 列（从 1 开始数）。'],['Anchor 是尺寸模板','anchor 提供一组预设宽高，帮助候选框从常见目标尺寸开始；它不是最终预测框，网络还会预测偏移和调整。'],['训练要把候选和真实框对应','匹配会考虑网格、anchor 尺寸与目标等规则；匹配到的候选参与相应监督。正/负样本是对训练分配结果的称呼，不是物体本身的固定属性。'],['多个尺度照顾不同大小','高分辨率特征图有更多位置格，较低分辨率特征图看更大范围。anchor 设计与多尺度输出共同影响候选覆盖。']],example:'中心 x=0.62、y=0.37；在 4×4 网格中列号=floor(0.62×4)+1=3，行号=floor(0.37×4)+1=2。',symbols:'归一化 x/y 范围通常是 0–1；floor 表示向下取整；anchor 的宽高单位需按当前实现核对。'},
    'yolo-loss':{title:'一个检测候选对应三类问题',parts:[['在哪：边界框位置','预测框和真实框位置不同就会有定位误差。IoU 量重叠；CIoU 还考虑框中心距离和长宽比例，具体公式按版本实现。'],['有没有：物体性 objectness','物体性分数回答这个位置的候选是否包含目标。背景候选按负例规则监督；匹配到的正位置，在常见 YOLOv5 实现中目标值可由预测框与真值框的 IoU 构造软值。'],['是什么：类别','在需要类别监督的正样本位置，类别分数与正确类别标签比较。物体性和类别是两个不同问题。'],['合成总损失','总损失通常把框、物体性、类别等分项乘权重再相加。权重、正负分配和具体目标值取决于仓库版本，不能只凭指标名字推断。']],example:'候选 A 位置准但类别错：定位项可较小，类别项仍会惩罚；候选 B 在背景处报高物体性：物体性项会惩罚误报。',symbols:'Lbox 是定位损失；Lobj 是物体性损失；Lcls 是分类损失；总损失是带权重的分项和。',advanced:{title:'CIoU 公式与分配细节',text:'CIoU 的中心距离、包围对角线和长宽比项需要先掌握坐标、交并集和三角/平方等基础。不同 YOLO 版本的匹配阈值与软目标处理有实现差异，建议对照当前 utils/loss.py。'}},
    'train-yolo':{title:'训练命令是一组可复核的实验设置',parts:[['先确认项目和终端位置','终端是输入命令的窗口；工作目录决定相对路径从哪里开始。先进入 YOLOv5 仓库根目录，再确认 Python 环境与依赖可用。'],['检查数据配置和标签','先用少量图片确认 data.yaml 路径、类别顺序、图片/标签配对和框位置。小规模试跑比一开始长时间训练更容易发现路径或格式错误。'],['逐项读训练参数','--data 指数据说明；--weights 指起始参数；--img 指输入尺寸；--batch 指每次处理样本数；--epochs 指遍历训练集的轮数。参数名随仓库版本可能变化。'],['日志和 checkpoint','训练日志记录损失、速度和验证指标；checkpoint 是训练过程保存的模型/状态文件。查看验证指标与预测图，不能只看训练损失下降。']],example:'示例 `--img 640 --batch 8 --epochs 2` 适合说明参数含义，不保证任何机器都能直接运行；先用本地 `train.py --help` 核对参数和显存。',symbols:'img 是输入边长示例；batch 是每批图片数；epochs 是完整遍历次数；data.yaml 中路径要匹配工作目录。'},
    'yolo-augment':{title:'配置文件分别控制数据、网络和训练设置',parts:[['data.yaml：数据与类别','写训练/验证数据在哪里、类别有多少及名称顺序。标签里的类别编号必须落在名称表范围内。'],['model.yaml：网络结构','写网络层、模块、通道和连接等结构信息。它决定计算图的蓝图，不包含训练后的所有权重数值。'],['hyp.yaml：超参数和增强','常见内容包括学习率、损失权重和增强幅度；具体字段随版本变化。一次实验尽量只改变一个设置。'],['增强必须同步标签','Mosaic 把多个图像块放入一张画布；几何变换后边界框要同步移动、缩放和裁切。颜色增强通常不移动框。']],example:'四张图拼成 Mosaic 后，一个框若被裁到画布外，只保留可见部分并按实现规则修正；不是把原坐标原封不动复制过去。',symbols:'data/model/hyp 是数据、结构和训练设置三类配置；字段含义以当前仓库读取配置的代码为准。'},
    inference:{title:'模型输出候选，后处理才得到最终框',parts:[['预处理整理图片','按训练时约定处理颜色顺序、尺寸、数值范围和补边。训练与推理预处理不一致会改变模型看到的输入。'],['模型产生原始预测','网络给出候选框相关数字、物体性和类别分数；还要解码坐标，并把分数组合成候选结果。'],['两个阈值解决不同问题','置信度阈值筛掉分数偏低的候选；NMS 的 IoU 阈值判断重叠候选是否重复。调高前者会减少候选，调低后者会更容易压制重叠框；都可能漏掉目标。'],['把坐标映回原图','若输入经过等比例缩放和补边，要先减去 padding，再除以缩放比例，最后按原图范围裁剪。']],example:'640×480 图 letterbox 到 640×640，若缩放比例为 1，上下各补 80 像素；预测框 y 坐标映回时先减 80。',symbols:'confidence threshold 是分数筛选门槛；IoU threshold 是重叠抑制门槛；两者不能混为一个阈值。',advanced:{title:'模型文件、运行时与速度指标',text:'ONNX 是模型交换表示；OpenVINO/TensorRT 是工具链及运行平台；latency 是单次等待时间，throughput 是单位时间处理量，FPS 是每秒帧数。文件、工具和硬件应分开比较。'}},
    debugging:{title:'排错要从可见现象沿流程往回查',parts:[['没有框：先核对输入和标注','打开原图和标签画框，确认类别编号、路径和预处理后目标仍可见。再逐步查看原始候选、分数门槛和 NMS 后结果。'],['类别总错：核对编号表','检查 data.yaml 的 names 顺序、标签 class id 范围和训练/推理使用的权重。类别数一致不代表类别顺序一致。'],['损失是 NaN：从最早异常值查','依次检查输入、模型输出、损失、梯度；缩小到一个 batch。NaN/Inf 是非有限数；0 是有效数，None 表示没有值。'],['一次只改一件事','保存失败图、命令、日志与配置；复制一份最小案例，一次只改一个原因，再观察同一指标是否恢复。']],example:'正常概率可以是 0；NaN 表示结果无效；None 表示没有对象。三者都不能简单用“等于 0”检查来代替。',symbols:'None 是空值；NaN 是非数值；Inf 是无穷大；三者在排错中应分别处理。'}
  };
  content.cnn.parts[1]=['把一个 3×3 窗口算成一个输出数','输入窗口是 [1,2,3; 4,5,6; 7,8,9]，卷积核是 [1,0,−1; 1,0,−1; 1,0,−1]。按对应位置相乘后相加：1−3+4−6+7−9=−6；偏置 b=0，所以这个位置输出 −6。互动区会把九次乘法逐项点亮。'];
  content.cnn.example='先用单通道小图手算：上面的 3×3 窗口与滤波器得到 −6；滑动窗口会在输出图的其他位置重复同一组权重。多通道时，先分别计算各通道贡献，再把它们相加并加偏置。';
  content.cnn.symbols='X 是输入像素或特征；K 是卷积核权重；b 是偏置；一次输出是所有对应乘积的和加 b。卷积步幅是窗口移动格数，padding 是边缘补出的格子。';
  const escape=value=>String(value).replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
  function render(lesson){
    const item=content[lesson?.id];if(!item)return '';
    const steps=item.parts.map((part,index)=>'<li><span class="depth-step-number">'+(index+1)+'</span><div><h4>'+escape(part[0])+'</h4><p>'+escape(part[1])+'</p></div></li>').join('');
    const advanced=item.advanced?'<details class="depth-advanced"><summary>选学深入：'+escape(item.advanced.title)+'</summary><p>'+escape(item.advanced.text)+'</p></details>':'';
    return '<section class="beginner-depth" id="foundation-notes-'+escape(lesson.id)+'" aria-labelledby="depth-title-'+escape(lesson.id)+'"><div class="beginner-depth-heading"><span class="chapter-kicker">ZERO-FOUNDATION · 逐步拆开讲</span><h2 id="depth-title-'+escape(lesson.id)+'">'+escape(item.title)+'</h2><p>下面先解释本章会用到的基础概念，再给一个能手算核对的例子。正文里的专业词也可以点开查看通俗解释和比喻。</p></div><ol class="depth-steps">'+steps+'</ol><div class="depth-worked"><strong>算一个具体例子</strong><p>'+escape(item.example)+'</p><p class="depth-symbols"><strong>符号对照：</strong>'+escape(item.symbols)+'</p></div>'+advanced+'</section>';
  }
  window.renderFoundationDepth=render;
})();
